#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "live_session_scene_candidate.h"
#include <iostream>
int main(){try{auto graph=loadGraph("work/roundtrip-11.dmx");RetainedShotTimelineCandidate timeline(graph,2237);size_t enabled=0,disabled=0;for(int32_t tick:{1259500,1392000}){auto step=evaluateLiveSessionSceneCandidate(timeline,tick,512,512);for(const auto&model:step.scene.models){auto*a=namedAttribute(timeline.graph(),timeline.graph().elements.at(model.id),"evaluateProceduralBones");if(!a||a->type!=4||a->values.size()!=1||a->values[0].wire.size()!=1||uint8_t(a->values[0].wire[0])>1)throw std::runtime_error("procedural setting schema");bool value=a->values[0].wire[0]!=0;if(model.evaluateProcedural!=value)throw std::runtime_error("scene dropped procedural setting");if(value)++enabled;else ++disabled;std::cout<<"tick="<<tick<<" model="<<model.id<<" evaluateProceduralBones="<<value<<" asset="<<model.placement.asset<<"\n";}}std::cout<<"saved procedural settings audited models="<<enabled+disabled<<" enabled="<<enabled<<" disabled="<<disabled<<" scene_setting_retained=1 native_flag_semantics=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
